  if(kind==='costs'){let labor=s.costs.find(c=>c.id===x.id);if(labor?.laborContract&&['laborContract','laborMeasurement','project','stage','supplier','description','document','category','amount','date','due','purchase'].some(k=>x[k]!==labor[k]))throw Error('Esta conta vem de uma medição de mão de obra. Altere a origem em Compras e notas → Contratos de mão de obra; aqui registre a baixa.');let linked=s.costs.find(c=>c.id===x.id);if(linked?.purchase&&['project','stage','supplier','description','category','amount','due','purchase','purchaseInstallment'].some(k=>x[k]!==linked[k]))throw Error('Esta conta é gerada por uma compra. Altere documento, itens ou parcelas na compra de origem; aqui registre o pagamento.');if((!x.stage&&!(x.fixedExpense&&(s.fixedExpenses||[]).some(f=>f.id===x.fixedExpense))&&!s.laborContracts?.some(c=>c.id===x.laborContract&&c.project===x.project&&c.scope==='Obra geral'))||!CATEGORIES.includes(x.category)||!x.description||!num(x.amount)||!x.due)throw Error('Preencha etapa, categoria, descrição, valor e vencimento.');for(let k of ['amount','incurred','paid'])if(!num(x[k])||x[k]<0)throw Error('Valores devem ser não negativos.');for(let k of ['paymentDiscount','paymentAddition'])if(x[k]!==undefined&&(!num(x[k])||x[k]<0))throw Error('Desconto e acréscimo devem ser não negativos.');if(costTotal(x)<0||x.incurred>x.amount||Math.round(x.paid*100)>Math.round(costTotal(x)*100))throw Error('Incorrido não pode exceder o original e pago não pode exceder o valor ajustado.');if(x.paid>0&&!x.paidDate)throw Error('Informe a data de pagamento.');}
  if(kind==='measurements'){let a=financialItems(s).find(t=>t.id===x.activity);if(!a||!x.number||!x.date||!num(x.quantity)||x.quantity<=0)throw Error('Informe medição, data, serviço e quantidade positiva.');let other=sum(s.measurements.filter(m=>m.id!==x.id&&m.activity===x.activity&&m.status!=='Glosada'),m=>m.quantity);if(other+Number(x.quantity)>(s.dataModel===2?a.quantity:a.executed)+0.000001)throw Error(s.dataModel===2?'Medições acumuladas não podem exceder a quantidade orçada.':'Medições acumuladas não podem exceder o executado.');if(x.status==='Apresentada'&&!x.submitted)throw Error('Informe a data de apresentação.');if(x.status==='Aprovada'&&(!x.approved||!x.submitted||!x.evidence))throw Error('Aprovação requer datas de apresentação e aprovação e referência da evidência.');}
  if(['receivableEntries','measurements'].includes(kind)&&x.receivableEntryAmount!==undefined){let value=x.receivableEntryAmount;if(!num(value)||value<0||Math.abs(value*100-Math.round(value*100))>.000001||kind==='receivableEntries'&&value>x.amount)throw Error('Informe uma entrada válida, em centavos, limitada ao total da cobrança.');if(value>0&&(!/^\d{4}-\d{2}-\d{2}$/.test(x.receivableEntryDue||'')||date(x.receivableEntryDue)?.toLocaleDateString('sv-SE')!==x.receivableEntryDue))throw Error('Informe o vencimento válido da entrada.');}
  if(['receivableEntries','measurements'].includes(kind)&&x.receivableInstallmentCount!==undefined&&(!Number.isInteger(x.receivableInstallmentCount)||x.receivableInstallmentCount<1||x.receivableInstallmentCount>120))throw Error('Informe de 1 a 120 parcelas a receber.');
  if(kind==='receipts'&&x.installmentId){let without=clone(s);without.receipts=without.receipts.filter(r=>r.id!==x.id);let row=receivableRows(without).find(r=>r.installmentId===x.installmentId&&(x.receivableId?r.manual&&r.sourceId===x.receivableId:!r.manual&&r.project===x.project&&r.number===x.number&&(r.type==='Retenção')===(x.receiptType==='Retenção')));if(!row||Math.round(Number(x.amount)*100)>Math.round(row.balance*100))throw Error('O recebimento ultrapassa o saldo disponível nesta parcela.');}
