  if(kind==='stockMoves'){let m=s.materials.find(m=>m.id===x.material);if(!m||m.project!==x.project||!x.date||!num(x.quantity)||x.quantity<=0||!['Entrada','Consumo','Perda'].includes(x.type))throw Error('Informe insumo válido, data, tipo e quantidade positiva.');if(x.type==='Perda'&&!x.reason)throw Error('Justifique a perda.');let prior=s.stockMoves.find(m=>m.id===x.id);let test=clone(s);test.stockMoves=test.stockMoves.filter(m=>m.id!==x.id);test.stockMoves.push(x);if(stock(test,m).available<0||prior&&stock(test,s.materials.find(m=>m.id===prior.material)).available<0)throw Error('Movimentação deixa o estoque negativo.');}
